            || mSandiumNotificationsDestroyed || mActivity == null
            || mSandiumNotificationDraw != null) return;
    if (NotificationPermissionController.sandiumNotificationPreferences()
                    .getBoolean("setup_completed", false)
            && !NotificationPermissionController.hasSandiumNotificationRequestPending()) return;
