    mSandiumNotificationTree = decor.getViewTreeObserver();
    mSandiumNotificationDraw = () -> {
        if (mSandiumNotificationsDestroyed || mSandiumNotificationFramePending
                || !NotificationPermissionController.hasSandiumNotificationRequestPending()) return;
        final Tab tab = mActivityTabProvider.get();
        if (tab == null || !isSandiumNotificationHomepageReady(tab)
                || !decor.isHardwareAccelerated()) return;
        final @Nullable View homepage = tab.getView();
        if (homepage == null) return;
        mSandiumNotificationFramePending = true;
        // Frame-commit is later than layout/onDraw: never prompt merely on navigation commit.
        decor.getViewTreeObserver().registerFrameCommitCallback(() -> decor.post(() -> {
            mSandiumNotificationFramePending = false;
            if (!isSandiumNotificationHomepageReady(tab) || homepage != tab.getView()
                    || !NotificationPermissionController.hasSandiumNotificationRequestPending()) return;
            if (mNotificationPermissionController == null) {
                mNotificationPermissionController = new NotificationPermissionController(
                        mWindowAndroid,
                        () -> new NotificationPermissionRationaleDialogController(
                                mActivity, mModalDialogManagerSupplier.get()),
                        tab.getProfile());
                NotificationPermissionController.attach(
                        mWindowAndroid, mNotificationPermissionController);
